}

function styleFor(id) {
  var isPair = false;
  if (state.contactForcePair === 'A-B normal pair') isPair = (id === 'N_BA' || id === 'N_AB');
  if (state.contactForcePair === 'A-B friction pair') isPair = (id === 'f_BA' || id === 'f_AB');
