function haloText(parent, txt, x, y, size, weight) {
  var t = parent.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size || 18, weight: weight || 'normal' })
    .fill('#000')
    .move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

function vectorText(parent, symbol, sub, x, y, size, weight) {
  var t = parent.text(function (add) {
    add.tspan(symbol + '\u20d7').font({ weight: weight || 'bold' });
    if (sub) {
      add.tspan(sub).font({ size: Math.round((size || 18) * 0.66), weight: weight || 'bold' })
        .attr({ 'baseline-shift': 'sub', dx: 1 });
    }
  }).font({ family: 'Arial, Helvetica, sans-serif', size: size || 18 })
    .fill('#000')
    .move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

function legendItem(parent, symbol, sub, desc, x, y) {
  var t = parent.text(function (add) {
    add.tspan(symbol + '\u20d7').font({ weight: 'bold' });
    if (sub) {
      add.tspan(sub).font({ size: 12, weight: 'bold' }).attr({ 'baseline-shift': 'sub', dx: 1 });
    }
    add.tspan(' = ' + desc).font({ weight: 'normal' }).attr({ dx: 7 });
  }).font({ family: 'Arial, Helvetica, sans-serif', size: 18 }).fill('#000').move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

