  var y2 = y + len * Math.sin(rad);
  var g = parent.group().opacity(st.opacity);

  if (st.pair) {
    g.line(x, y, x2, y2).stroke({ color: '#ffb9b9', width: 10, linecap: 'round' }).opacity(0.65);
