  var line = g.line(x, y, x2, y2)
    .stroke({ color: st.color, width: st.width, linecap: 'round' })
    .attr({ 'marker-end': st.pair ? 'url(#arrowStrongRed)' : 'url(#arrowRed)' });

  var label = vectorText(g, symbol, sub, lx, ly, 18, 'bold');
  if (st.pair) label.fill(strongRed);

