  drawForce(topFBD, 'N_BA', 145, 95, normalAng, 78, 'N', 'BA', 118, 7,
    'Normal force exerted by B on A; it acts on A and points perpendicular to the contact.',
    'N_BA acts on A',
    'This is the normal force exerted by block B on block A. Its equal-and-opposite partner, N_AB, acts on block B and therefore appears on the other free-body diagram.');
  drawForce(topFBD, 'T', 145, 95, slopeAng, 74, 'T', '', 218, 66,
    'Tension pulls block A up the incline.',
    'Tension acts on A',
    'The cord is attached to block A, so the tension force is drawn only in the free-body diagram for A.');
  drawForce(topFBD, 'f_BA', 145, 95, aFrictionAng, 70, 'f', 'BA', 46, 63,
    'Friction exerted by B on A; it lies along the A-B contact surface.',
    'f_BA acts on A',
    'This friction force acts on block A. Reversing the relative sliding tendency reverses this arrow along the contact surface.');
  drawForce(topFBD, 'w_A', 145, 95, 90, 72, 'w', 'A', 157, 137,
    'Weight of block A points vertically downward.',
    'Weight of A',
    'Weight is Earth’s gravitational force on block A, so it belongs on A’s free-body diagram.');
  topFBD.circle(14).center(145, 95).fill('#000').front();

  drawReference(botFBD, 145, 365);
  drawForce(botFBD, 'N_B', 145, 365, normalAng, 75, 'N', 'B', 107, 286,
    'Normal force exerted by the incline plane on B; it acts on B.',
    'N_B acts on B',
    'This contact force comes from the incline plane, not from block A. It is perpendicular to the plane and belongs on B’s free-body diagram.');
  drawForce(botFBD, 'f_AB', 145, 365, bFromAFrictionAng, 66, 'f', 'AB', 181, 309,
    'Friction exerted by A on B; it is opposite to f_BA.',
    'f_AB acts on B',
    'The A-B friction forces are a third-law pair. f_BA acts on A, while f_AB acts on B in the opposite direction.');
  drawForce(botFBD, 'f_B', 145, 365, planeFrictionAng, 77, 'f', 'B', 244, 352,
    'Friction exerted by the incline plane on B.',
    'f_B acts on B',
    'This is a separate friction force from the plane on block B. It is not the third-law partner of f_AB because those forces come from different contacts.');
  drawForce(botFBD, 'N_AB', 145, 365, downNormalAng, 58, 'N', 'AB', 158, 414,
    'Normal force exerted by A on B; it is opposite to N_BA.',
    'N_AB acts on B',
    'This normal force is exerted by A on B. It is paired with N_BA, but it belongs only on B’s free-body diagram.');
  drawForce(botFBD, 'w_B', 145, 365, 90, 64, 'w', 'B', 90, 408,
    'Weight of block B points vertically downward.',
    'Weight of B',
    'Weight is Earth’s gravitational force on block B, so it belongs on B’s free-body diagram.');
  botFBD.circle(14).center(145, 365).fill('#000').front();

  updatePanelOpacity();
}

