function updatePanelOpacity() {
  topPanel.opacity(state.selectedBody === 'B' ? 0.38 : 1);
  botPanel.opacity(state.selectedBody === 'A' ? 0.38 : 1);
  legendLayer.opacity(1);

  var aBtn = document.getElementById('isolateBodyAInput');
  var bBtn = document.getElementById('isolateBodyBInput');
  var bothBtn = document.getElementById('isolateBodyBothInput');
  if (aBtn) aBtn.className = state.selectedBody === 'A' ? 'active' : '';
  if (bBtn) bBtn.className = state.selectedBody === 'B' ? 'active' : '';
  if (bothBtn) bothBtn.className = state.selectedBody === 'both' ? 'active' : '';

  var pairOut = document.getElementById('contactForcePairVal');
  if (pairOut) {
    pairOut.textContent = state.highlightPair ? (state.pair === 'normal' ? 'A-B normal pair' : 'A-B friction pair') : 'off';
    pairOut.value = pairOut.textContent;
  }
  var slideOut = document.getElementById('slidingTendencyVal');
  if (slideOut) {
    slideOut.textContent = state.slidingTendency;
    slideOut.value = state.slidingTendency;
  }
}

function selectBody(body) {
  state.selectedBody = body;
  renderFBDs();
  if (body === 'A') {
    showPopup('Block A isolated', 'The upper diagram contains only forces acting on A. The partner forces that A exerts on B are excluded because they do not act on A.');
  } else if (body === 'B') {
    showPopup('Block B isolated', 'The lower diagram contains only forces acting on B. Contact forces from A and from the incline appear here because they act directly on B.');
  } else {
    hidePopup();
  }
}

function toggle_contactForcePair(on) {
  state.highlightPair = !!on;
  renderFBDs();
}

function trigger_pairChoice() {
  state.pair = state.pair === 'normal' ? 'friction' : 'normal';
  state.highlightPair = true;
  var cb = document.getElementById('contactForcePairInput');
  if (cb) cb.checked = true;
  renderFBDs();
  showPopup(
    state.pair === 'normal' ? 'A-B normal pair' : 'A-B friction pair',
    state.pair === 'normal'
      ? 'The two normal forces from the A-B contact point in opposite perpendicular directions, but N_BA acts on A and N_AB acts on B.'
      : 'The two friction forces from the A-B contact are parallel to the contact surface and opposite in direction, but f_BA acts on A and f_AB acts on B.'
  );
}

function toggle_slidingTendency(on) {
  state.slidingTendency = on ? 'A tends down on B' : 'A tends up on B';
  renderFBDs();
}

var demoSteps = [
  {
    title: 'Isolate one block',
    narration: 'Click block A or block B in the incline sketch. The selected free-body diagram contains only forces acting on that block.',
    state: { highlightPair: false, pair: 'normal', slidingTendency: 'A tends up on B' }
  },
  {
    title: 'Compare the normal pair',
    narration: 'N_BA appears on A while N_AB appears on B. The two normal forces are opposite, but they act on different objects.',
    state: { highlightPair: true, pair: 'normal', slidingTendency: 'A tends up on B' }
  },
  {
    title: 'Compare the friction pair',
    narration: 'f_BA and f_AB are parallel to the contact surface and opposite in direction, with one force on each isolated body.',
    state: { highlightPair: true, pair: 'friction', slidingTendency: 'A tends up on B' }
  },
  {
    title: 'Reverse sliding tendency',
    narration: 'Reverse the relative sliding tendency. The friction arrows reverse along the contact surfaces.',
    state: { highlightPair: true, pair: 'friction', slidingTendency: 'A tends down on B' }
  }
];

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[state.step];
  state.selectedBody = 'both';
  state.highlightPair = step.state.highlightPair;
  state.pair = step.state.pair;
  state.slidingTendency = step.state.slidingTendency;

  var pairInput = document.getElementById('contactForcePairInput');
  var slideInput = document.getElementById('slidingTendencyInput');
  if (pairInput) pairInput.checked = state.highlightPair;
  if (slideInput) slideInput.checked = state.slidingTendency === 'A tends down on B';

  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = step.narration;
  if (lab) lab.textContent = (state.step + 1) + '/4 ' + step.title;

  renderFBDs();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
